"use client";

import { FormEvent, ReactNode, useMemo, useRef, useState } from "react";
import type {
  ActionFn, AppData, CalendarEvent, FinanceAccount, FinanceBudget, FinanceCategory,
  FinanceObligation, FinanceOccurrence, FinanceTransaction, Project, Task,
} from "@/lib/app-types";
import { Icon } from "@/components/icons";
import { calculateRemainingIncomeForMonth, normalizeBankName, transferFeeFor } from "@/lib/finance-math";
import { matchesMovementFilters, type MovementFilters } from "@/lib/finance-filters";
import { TransferTransactionForm } from "@/components/transfer-transaction-form";
import { ConceptInput } from "@/components/concept-input";
import { BudgetAssignmentModal, BudgetPanel, GoalFormModal, GoalsPanel } from "@/components/finance-goals-budget";

export const localToday = () => {
  const parts = new Intl.DateTimeFormat("en-US", { timeZone: "America/Santo_Domingo", year: "numeric", month: "2-digit", day: "2-digit" }).formatToParts(new Date());
  const part = (type: string) => parts.find((item) => item.type === type)?.value || "";
  return `${part("year")}-${part("month")}-${part("day")}`;
};
export const money = (minor: number | null | undefined) => ((minor || 0) / 100).toLocaleString("es-DO", { style: "currency", currency: "DOP", maximumFractionDigits: 2 });
export const legacyMoney = (amount: number | null | undefined) => amount == null ? "—" : amount.toLocaleString("es-DO", { style: "currency", currency: "DOP", maximumFractionDigits: 2 });
export const dateLabel = (value: string | null | undefined) => value ? new Date(`${value.slice(0, 10)}T12:00:00`).toLocaleDateString("es-DO", { day: "2-digit", month: "short", year: "numeric" }) : "Sin fecha";
const minor = (value: string) => Math.round((Number(value) || 0) * 100);
const pad = (value: number) => String(value).padStart(2, "0");
const monthKey = () => localToday().slice(0, 7);
const names = { income: "Ingreso", expense: "Gasto", transfer: "Transferencia", adjustment: "Ajuste" } as Record<string, string>;

export function Modal({ title, children, onClose, wide = false }: { title: string; children: ReactNode; onClose: () => void; wide?: boolean }) {
  return <div className="overlay v2overlay" role="presentation" onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
    <section className={`dialog ${wide ? "wideDialog" : ""}`} role="dialog" aria-modal="true" aria-label={title}>
      <div className="dialogHead"><h2>{title}</h2><button type="button" aria-label="Cerrar" onClick={onClose}>×</button></div>
      <div className="dialogBody">{children}</div>
    </section>
  </div>;
}

function Empty({ children }: { children: ReactNode }) { return <div className="empty compactEmpty">{children}</div>; }
function MiniProgress({ value, tone = "blue" }: { value: number; tone?: string }) { return <div className="progress"><span className={tone} style={{ width: `${Math.max(0, Math.min(100, value))}%` }} /></div>; }
function Metric({ label, value, help, detail, tone }: { label: string; value: ReactNode; help: string; detail?: ReactNode; tone?: string }) { return <div className={`metric ${tone || ""}`}><span>{label}</span><b>{value}</b><small>{help}</small>{detail && <small className="metricDetail">{detail}</small>}</div>; }

export function eventOccursOn(event: CalendarEvent, date: string) {
  if (event.status === "cancelled" || date < event.startDate) return false;
  const until = event.recurrenceUntil || event.endDate;
  if (event.recurrence === "none") return date >= event.startDate && date <= event.endDate;
  if (until && date > until) return false;
  const start = new Date(`${event.startDate}T12:00:00`);
  const current = new Date(`${date}T12:00:00`);
  const diff = Math.floor((current.getTime() - start.getTime()) / 86400000);
  if (event.recurrence === "daily") return diff >= 0;
  if (event.recurrence === "weekly") return diff >= 0 && diff % 7 === 0;
  if (event.recurrence === "monthly") return current.getDate() === start.getDate();
  if (event.recurrence === "yearly") return current.getDate() === start.getDate() && current.getMonth() === start.getMonth();
  return false;
}

type CalendarItem = { id: string; kind: "task" | "event"; title: string; date: string; start: string; end: string; done?: boolean; areaName?: string; projectName?: string; contextColor?: string; source: Task | CalendarEvent };

export function CalendarModule({ data, act, openTask, newTask }: { data: AppData; act: ActionFn; openTask: (task: Task) => void; newTask: (date: string) => void }) {
  const [mode, setMode] = useState<"month" | "week" | "day" | "agenda">("month");
  const [month, setMonth] = useState(monthKey());
  const [selected, setSelected] = useState(localToday());
  const [eventModal, setEventModal] = useState(false);
  const [editingEventId, setEditingEventId] = useState<string | null>(null);
  const [assignId, setAssignId] = useState("");
  const [form, setForm] = useState({ title: "", description: "", location: "", startDate: selected, endDate: selected, startTime: "", endTime: "", allDay: true, recurrence: "none", recurrenceUntil: "", areaId: "", projectId: "", linkedTaskId: "", notes: "" });
  const changeForm = (field: keyof typeof form, next: string | boolean) => setForm((current) => ({ ...current, [field]: next }));
  const activeTasks = data.tasks.filter((t) => !t.archived);
  const contextFor = (areaId: string | null, projectId: string | null) => { const area = data.areas.find((x) => x.id === areaId), project = data.projects.find((x) => x.id === projectId); return { areaName: area?.name, projectName: project?.name, contextColor: area?.color }; };
  const itemsFor = (date: string): CalendarItem[] => [
    ...activeTasks.filter((t) => t.scheduledDate === date).map((t) => ({ id: t.id, kind: "task" as const, title: t.title, date, start: t.scheduledStartTime, end: t.scheduledEndTime, done: t.done, ...contextFor(t.areaId, t.projectId), source: t })),
    ...data.events.filter((e) => eventOccursOn(e, date)).map((e) => ({ id: e.id, kind: "event" as const, title: e.title, date, start: e.startTime, end: e.endTime, ...contextFor(e.areaId, e.projectId), source: e })),
  ].sort((a, b) => (a.start || "99:99").localeCompare(b.start || "99:99"));
  const selectedItems = itemsFor(selected);
  const unscheduled = activeTasks.filter((t) => !t.done && !t.scheduledDate);
  const collisions = useMemo(() => {
    if (form.allDay || !form.startTime || !form.endTime) return [] as CalendarItem[];
    return itemsFor(form.startDate).filter((x) => x.start && x.end && form.startTime < x.end && form.endTime > x.start);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [form.startDate, form.startTime, form.endTime, form.allDay, data.events, data.tasks]);
  const [y, m] = month.split("-").map(Number);
  const first = new Date(y, m - 1, 1);
  const offset = (first.getDay() + 6) % 7;
  const days = new Date(y, m, 0).getDate();
  const dateAt = (d: number) => `${y}-${pad(m)}-${pad(d)}`;
  const shiftMonth = (n: number) => { const d = new Date(y, m - 1 + n, 1); setMonth(`${d.getFullYear()}-${pad(d.getMonth() + 1)}`); };
  const openNewEvent = (date = selected) => { setEditingEventId(null); setForm({ title: "", description: "", location: "", startDate: date, endDate: date, startTime: "", endTime: "", allDay: true, recurrence: "none", recurrenceUntil: "", areaId: "", projectId: "", linkedTaskId: "", notes: "" }); setEventModal(true); };
  const openExistingEvent = (event: CalendarEvent) => { setEditingEventId(event.id); setForm({ title:event.title,description:event.description,location:event.location,startDate:event.startDate,endDate:event.endDate,startTime:event.startTime,endTime:event.endTime,allDay:event.allDay,recurrence:event.recurrence,recurrenceUntil:event.recurrenceUntil,areaId:event.areaId||"",projectId:event.projectId||"",linkedTaskId:event.linkedTaskId||"",notes:event.notes }); setEventModal(true); };
  const submitEvent = async (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const fields=Object.fromEntries(new FormData(e.currentTarget).entries()); await act(editingEventId ? "event.update" : "event.create", { ...fields, id:editingEventId, status:"scheduled", allDay: fields.allDay === "on", timezone: data.finance.settings.timezone }); setEventModal(false); setEditingEventId(null); };
  const horizon = Array.from({ length: mode === "day" ? 1 : mode === "week" ? 7 : 45 }, (_, i) => {
    const base = new Date(`${mode === "day" ? selected : mode === "week" ? selected : localToday()}T12:00:00`);
    if (mode === "week") base.setDate(base.getDate() - ((base.getDay() + 6) % 7) + i);
    else base.setDate(base.getDate() + i);
    return `${base.getFullYear()}-${pad(base.getMonth() + 1)}-${pad(base.getDate())}`;
  });
  const conflictCount = horizon.reduce((n, d) => {
    const timed = itemsFor(d).filter((x) => x.start && x.end);
    return n + timed.filter((x, i) => timed.slice(i + 1).some((z) => x.start < z.end && x.end > z.start)).length;
  }, 0);

  return <>
    <div className="metrics">
      <Metric label="Programadas hoy" value={itemsFor(localToday()).length} help="Tareas y eventos" />
      <Metric label="Tareas sin día" value={unscheduled.length} help="Disponibles para planificar" />
      <Metric label="Eventos activos" value={data.events.filter((e) => e.status !== "cancelled").length} help="Incluye recurrencias" />
      <Metric label="Posibles solapamientos" value={conflictCount} help="En el horizonte visible" tone={conflictCount ? "warningMetric" : ""} />
    </div>
    <div className="subnav">
      {(["month", "week", "day", "agenda"] as const).map((x) => <button className={mode === x ? "active" : ""} onClick={() => setMode(x)} key={x}>{x === "month" ? "Mes" : x === "week" ? "Semana" : x === "day" ? "Día" : "Agenda"}</button>)}
      <span />
      <button className="primary" onClick={() => openNewEvent()}>＋ Evento</button>
    </div>
    {mode === "month" ? <div className="twocol planningGrid">
      <section className="panel">
        <div className="calendarHead"><button onClick={() => shiftMonth(-1)}>←</button><h2>{first.toLocaleDateString("es-DO", { month: "long", year: "numeric" })}</h2><button onClick={() => shiftMonth(1)}>→</button></div>
        <div className="calendar"><div className="calendarWeek">{["Lun", "Mar", "Mié", "Jue", "Vie", "Sáb", "Dom"].map((x) => <span key={x}>{x}</span>)}</div><div className="calendarDays">
          {Array.from({ length: offset }, (_, i) => <span className="emptyDay" key={`blank-${i}`} />)}
          {Array.from({ length: days }, (_, i) => { const date = dateAt(i + 1); const items = itemsFor(date); return <button key={date} className={`calendarDay ${selected === date ? "selected" : ""} ${date === localToday() ? "today" : ""}`} onClick={() => setSelected(date)}><b>{i + 1}</b>{items.slice(0, 2).map((x) => <small className={x.kind} style={x.contextColor ? { borderLeft: `3px solid ${x.contextColor}` } : undefined} key={`${x.kind}-${x.id}`}>{x.start ? `${x.start} ` : ""}{x.title}</small>)}{items.length > 2 && <em>+{items.length - 2}</em>}</button>; })}
        </div></div>
      </section>
      <DayPanel date={selected} items={selectedItems} tasks={unscheduled} openTask={openTask} editEvent={openExistingEvent} onEvent={() => openNewEvent(selected)} onNewTask={() => newTask(selected)} assignId={assignId} setAssignId={setAssignId} assign={async () => { if (!assignId) return; await act("updateTask", { id: assignId, scheduledDate: selected }); setAssignId(""); }} cancelEvent={(id) => act("event.cancel", { id })} />
    </div> : <section className="panel agendaPanel">
      <div className="panelHead"><div><h2>{mode === "day" ? dateLabel(selected) : mode === "week" ? "Semana seleccionada" : "Próximos 45 días"}</h2><p className="soft">La agenda distingue acciones y eventos; los eventos recurrentes se proyectan sin duplicar registros.</p></div>{mode !== "agenda" && <input type="date" value={selected} onChange={(e) => setSelected(e.target.value)} />}</div>
      {horizon.map((date) => { const items = itemsFor(date); if (mode === "agenda" && !items.length) return null; return <div className="agendaDay" key={date}><div className="agendaDate"><b>{new Date(`${date}T12:00:00`).toLocaleDateString("es-DO", { weekday: "short", day: "2-digit" })}</b><small>{new Date(`${date}T12:00:00`).toLocaleDateString("es-DO", { month: "short" })}</small></div><div>{items.length ? items.map((x) => <CalendarRow item={x} openTask={openTask} editEvent={openExistingEvent} cancelEvent={(id) => act("event.cancel", { id })} key={`${date}-${x.kind}-${x.id}`} />) : <span className="soft">Sin actividades</span>}</div></div>; })}
    </section>}
    {eventModal && <Modal title={editingEventId ? "Editar evento" : "Nuevo evento"} onClose={() => setEventModal(false)}><form className="form" onSubmit={submitEvent}>
      <label>Título*<input name="title" required autoFocus value={form.title} onChange={(e) => changeForm("title", e.target.value)} /></label>
      <div className="formgrid"><label>Inicio<input name="startDate" required type="date" value={form.startDate} onChange={(e) => { changeForm("startDate", e.target.value); if(e.target.value>form.endDate) changeForm("endDate",e.target.value); }} /></label><label>Final<input name="endDate" required type="date" min={form.startDate} value={form.endDate} onChange={(e) => changeForm("endDate", e.target.value)} /></label></div>
      <label className="inlineCheck"><input name="allDay" type="checkbox" checked={form.allDay} onChange={(e) => changeForm("allDay", e.target.checked)} /> Todo el día</label>
      {!form.allDay && <div className="formgrid"><label>Hora de inicio<input name="startTime" required type="time" value={form.startTime} onInput={(e) => changeForm("startTime", (e.target as HTMLInputElement).value)} onChange={(e) => changeForm("startTime", e.target.value)} /></label><label>Hora final<input name="endTime" required type="time" min={form.startTime} value={form.endTime} onInput={(e) => changeForm("endTime", (e.target as HTMLInputElement).value)} onChange={(e) => changeForm("endTime", e.target.value)} /></label></div>}
      {collisions.length > 0 && <div className="warningBox"><b>Posible conflicto de horario</b><span>Coincide con {collisions.map((x) => x.title).join(", ")}. Puedes guardarlo, pero conviene revisar el día.</span></div>}
      <div className="formgrid"><label>Repetición<select name="recurrence" value={form.recurrence} onChange={(e) => changeForm("recurrence", e.target.value)}><option value="none">No se repite</option><option value="daily">Diaria</option><option value="weekly">Semanal</option><option value="monthly">Mensual</option><option value="yearly">Anual</option></select></label>{form.recurrence !== "none" && <label>Repetir hasta<input name="recurrenceUntil" type="date" min={form.startDate} value={form.recurrenceUntil} onChange={(e) => changeForm("recurrenceUntil", e.target.value)} /></label>}</div>
      <div className="formgrid"><label>Área<select name="areaId" value={form.areaId} onChange={(e) => changeForm("areaId", e.target.value)}><option value="">Sin área</option>{data.areas.map((x) => <option value={x.id} key={x.id}>{x.name}</option>)}</select></label><label>Proyecto<select name="projectId" value={form.projectId} onChange={(e) => changeForm("projectId", e.target.value)}><option value="">Sin proyecto</option>{data.projects.map((x) => <option value={x.id} key={x.id}>{x.name}</option>)}</select></label></div>
      <label>Ubicación<input name="location" value={form.location} onChange={(e) => changeForm("location", e.target.value)} /></label>
      <label>Descripción<textarea name="description" value={form.description} onChange={(e) => changeForm("description", e.target.value)} /></label>
      <div className="formActions"><button type="button" onClick={() => setEventModal(false)}>Cancelar</button><button className="primary">Guardar evento</button></div>
    </form></Modal>}
  </>;
}

function DayPanel({ date, items, tasks, openTask, editEvent, onEvent, onNewTask, assignId, setAssignId, assign, cancelEvent }: { date: string; items: CalendarItem[]; tasks: Task[]; openTask: (task: Task) => void; editEvent:(event:CalendarEvent)=>void; onEvent: () => void; onNewTask: () => void; assignId: string; setAssignId: (x: string) => void; assign: () => void; cancelEvent: (id: string) => void }) {
  return <section className="panel dayPanel"><div className="panelHead"><div><h2>{dateLabel(date)}</h2><span className="soft">{items.length} actividad{items.length === 1 ? "" : "es"}</span></div><div className="buttonRow"><button onClick={onEvent}>Evento</button><button className="primary" onClick={onNewTask}>＋ Tarea</button></div></div>
    {items.length ? items.map((x) => <CalendarRow item={x} openTask={openTask} editEvent={editEvent} cancelEvent={cancelEvent} key={`${x.kind}-${x.id}`} />) : <Empty>No hay nada programado para este día.</Empty>}
    <div className="scheduleSection"><h3>Asignar una tarea existente</h3><div className="inlineForm"><select value={assignId} onChange={(e) => setAssignId(e.target.value)}><option value="">Selecciona una tarea sin día…</option>{tasks.map((x) => <option value={x.id} key={x.id}>{x.title}</option>)}</select><button disabled={!assignId} onClick={assign}>Asignar</button></div></div>
  </section>;
}

function CalendarRow({ item, openTask, editEvent, cancelEvent }: { item: CalendarItem; openTask: (task: Task) => void; editEvent:(event:CalendarEvent)=>void; cancelEvent: (id: string) => void }) {
  return <div className={`calendarRow ${item.kind}`}><i style={item.contextColor ? { background: item.contextColor, boxShadow: `0 0 0 4px ${item.contextColor}22` } : undefined} /><button onClick={() => item.kind === "task" ? openTask(item.source as Task) : editEvent(item.source as CalendarEvent)}><b>{item.title}</b><small>{item.kind === "task" ? "Tarea" : "Evento"}{item.start ? ` · ${item.start}${item.end ? `–${item.end}` : ""}` : " · Todo el día"}</small>{(item.areaName || item.projectName) && <span className="calendarContexts">{item.areaName && <span className="contextBadge areaContext">Área: {item.areaName}</span>}{item.projectName && <span className="contextBadge projectContext"><Icon name="folder" size={10} />{item.projectName}</span>}</span>}</button>{item.kind === "event" && <button className="iconDanger" title="Cancelar evento" onClick={() => cancelEvent(item.id)}>×</button>}</div>;
}

export function ProjectsModule({ data, act, openTask }: { data: AppData; act: ActionFn; openTask: (task: Task) => void }) {
  const [areaModal, setAreaModal] = useState(false);
  const [projectModal, setProjectModal] = useState(false);
  const [editingAreaId, setEditingAreaId] = useState<string | null>(null);
  const [editingProjectId, setEditingProjectId] = useState<string | null>(null);
  const [area, setArea] = useState({ name: "", color: "#2463eb" });
  const [project, setProject] = useState({ name: "", areaId: "", description: "", status: "active", startDate: "", targetDate: "", budget: "" });
  const tasks = data.tasks.filter((x) => !x.archived);
  const activeProjects = data.projects.filter((x) => x.status === "active");
  const unassigned = tasks.filter((x) => !x.projectId).length;
  const projectTasks = (id: string) => tasks.filter((x) => x.projectId === id);
  const areaFor = (id: string | null) => data.areas.find((x) => x.id === id);
  const newArea = () => { setEditingAreaId(null); setArea({ name: "", color: "#2463eb" }); setAreaModal(true); };
  const editArea = (value: AppData["areas"][number]) => { setEditingAreaId(value.id); setArea({ name: value.name, color: value.color }); setAreaModal(true); };
  const newProject = () => { setEditingProjectId(null); setProject({ name: "", areaId: "", description: "", status: "active", startDate: "", targetDate: "", budget: "" }); setProjectModal(true); };
  const editProject = (value: Project) => { setEditingProjectId(value.id); setProject({ name: value.name, areaId: value.areaId || "", description: value.description, status: value.status, startDate: value.startDate, targetDate: value.targetDate, budget: value.budgetMinor == null ? "" : String(value.budgetMinor / 100) }); setProjectModal(true); };
  return <>
    <div className="metrics"><Metric label="Áreas" value={data.areas.length} help="Ámbitos permanentes" /><Metric label="Proyectos activos" value={activeProjects.length} help="Resultados con principio y fin" /><Metric label="Tareas sin proyecto" value={unassigned} help="Pueden seguir siendo acciones sueltas" /><Metric label="Inversión en proyectos" value={money(activeProjects.reduce((s, x) => s + x.spentMinor, 0))} help="Desde movimientos vinculados" /></div>
    <div className="subnav"><button onClick={newArea}><Icon name="plus" size={16} />Área</button><button className="primary" onClick={newProject}><Icon name="plus" size={16} />Proyecto</button></div>
    <section className="panel"><div className="panelHead"><div><h2>Áreas de vida</h2><p className="soft">Las áreas no se completan; sirven para mantener en equilibrio hogar, familia, salud, trabajo y otros ámbitos.</p></div></div><div className="areaGrid">{data.areas.map((x) => { const areaTasks = tasks.filter((t) => t.areaId === x.id); return <div className="areaCard" key={x.id}><i style={{ background: x.color }} /><div className="areaCardHead"><b>{x.name}</b><button className="editIcon" title={`Editar ${x.name}`} aria-label={`Editar área ${x.name}`} onClick={() => editArea(x)}><Icon name="pencil" size={14} /></button></div><span>{areaTasks.filter((t) => !t.done).length} pendientes · {data.projects.filter((p) => p.areaId === x.id && p.status === "active").length} proyectos</span></div>; })}</div></section>
    <section className="panel"><div className="panelHead"><div><h2>Proyectos</h2><p className="soft">El avance se calcula con sus tareas; el gasto proviene exclusivamente de transacciones financieras vinculadas.</p></div></div>{data.projects.length ? <div className="projectGrid">{data.projects.map((p) => { const pt = projectTasks(p.id), done = pt.filter((x) => x.done).length, progress = pt.length ? done / pt.length * 100 : 0, financial = p.budgetMinor ? p.spentMinor / p.budgetMinor * 100 : 0; return <article className="projectCard" key={p.id}><div className="projectTop"><span><i style={{ background: areaFor(p.areaId)?.color || "#8492a6" }} />{areaFor(p.areaId)?.name || "Sin área"}</span><div className="projectTopActions"><span className={`status ${p.status}`}>{p.status === "active" ? "Activo" : p.status === "completed" ? "Completado" : "En pausa"}</span><button className="editIcon" title={`Editar ${p.name}`} aria-label={`Editar proyecto ${p.name}`} onClick={() => editProject(p)}><Icon name="pencil" size={14} /></button></div></div><h3>{p.name}</h3><p>{p.description || "Sin descripción"}</p><div className="projectStats"><span><b>{Math.round(progress)}%</b>avance</span><span><b>{done}/{pt.length}</b>tareas</span><span><b>{money(p.spentMinor)}</b>gastado</span></div><MiniProgress value={progress} /><div className="budgetMini"><span>{p.budgetMinor == null ? "Sin presupuesto" : `${money(p.spentMinor)} de ${money(p.budgetMinor)}`}</span>{p.budgetMinor != null && <b className={financial > 100 ? "negative" : ""}>{Math.round(financial)}%</b>}</div>{pt.slice(0, 3).map((t) => <button className="projectTask" onClick={() => openTask(t)} key={t.id}><span className={t.done ? "checkDone" : ""}>{t.done ? "✓" : "○"}</span>{t.title}</button>)}{p.targetDate && <small className="projectDue">Objetivo: {dateLabel(p.targetDate)}</small>}</article>; })}</div> : <Empty>Crea tu primer proyecto para agrupar tareas con un resultado concreto.</Empty>}</section>
    <section className="panel"><div className="panelHead"><div><h2>Clasificar tareas</h2><p className="soft">Asigna contexto sin cambiar la jerarquía de tareas y subtareas.</p></div></div><div className="tableWrap"><table><thead><tr><th>Tarea</th><th>Área</th><th>Proyecto</th><th>Horario</th></tr></thead><tbody>{tasks.filter((t) => !t.done).slice(0, 30).map((t) => <tr key={t.id}><td><button className="lineTitle" onClick={() => openTask(t)}>{t.title}</button></td><td><select value={t.areaId || ""} onChange={(e) => act("task.context", { id: t.id, areaId: e.target.value, projectId: t.projectId, scheduledStartTime: t.scheduledStartTime, scheduledEndTime: t.scheduledEndTime })}><option value="">Sin área</option>{data.areas.map((x) => <option value={x.id} key={x.id}>{x.name}</option>)}</select></td><td><select value={t.projectId || ""} onChange={(e) => act("task.context", { id: t.id, areaId: t.areaId, projectId: e.target.value, scheduledStartTime: t.scheduledStartTime, scheduledEndTime: t.scheduledEndTime })}><option value="">Sin proyecto</option>{data.projects.map((x) => <option value={x.id} key={x.id}>{x.name}</option>)}</select></td><td>{t.scheduledStartTime ? `${t.scheduledStartTime}${t.scheduledEndTime ? `–${t.scheduledEndTime}` : ""}` : "Todo el día"}</td></tr>)}</tbody></table></div></section>
    {areaModal && <Modal title={editingAreaId ? "Editar área" : "Nueva área"} onClose={() => setAreaModal(false)}><form className="form" onSubmit={async (e) => { e.preventDefault(); await act(editingAreaId ? "area.update" : "area.create", { id: editingAreaId, ...area }); setAreaModal(false); }}><label>Nombre*<input required autoFocus value={area.name} onChange={(e) => setArea({ ...area, name: e.target.value })} /></label><label>Color<input type="color" value={area.color} onChange={(e) => setArea({ ...area, color: e.target.value })} /></label><div className="formActions"><button type="button" onClick={() => setAreaModal(false)}>Cancelar</button><button className="primary">{editingAreaId ? "Guardar cambios" : "Crear área"}</button></div></form></Modal>}
    {projectModal && <Modal title={editingProjectId ? "Editar proyecto" : "Nuevo proyecto"} onClose={() => setProjectModal(false)}><form className="form" onSubmit={async (e) => { e.preventDefault(); await act(editingProjectId ? "project.update" : "project.create", { id: editingProjectId, ...project, budgetMinor: project.budget ? minor(project.budget) : null }); setProjectModal(false); }}><label>Nombre*<input required autoFocus value={project.name} onChange={(e) => setProject({ ...project, name: e.target.value })} /></label><div className="formgrid"><label>Área<select value={project.areaId} onChange={(e) => setProject({ ...project, areaId: e.target.value })}><option value="">Sin área</option>{data.areas.map((x) => <option value={x.id} key={x.id}>{x.name}</option>)}</select></label><label>Estado<select value={project.status} onChange={(e) => setProject({ ...project, status: e.target.value })}><option value="active">Activo</option><option value="paused">En pausa</option><option value="completed">Completado</option></select></label></div><label>Descripción<textarea value={project.description} onChange={(e) => setProject({ ...project, description: e.target.value })} /></label><div className="formgrid"><label>Inicio<input type="date" value={project.startDate} onChange={(e) => setProject({ ...project, startDate: e.target.value })} /></label><label>Fecha objetivo<input type="date" min={project.startDate} value={project.targetDate} onChange={(e) => setProject({ ...project, targetDate: e.target.value })} /></label></div><label>Presupuesto estimado RD$<input type="number" min="0" step="0.01" value={project.budget} onChange={(e) => setProject({ ...project, budget: e.target.value })} /></label><div className="formActions"><button type="button" onClick={() => setProjectModal(false)}>Cancelar</button><button className="primary">{editingProjectId ? "Guardar cambios" : "Crear proyecto"}</button></div></form></Modal>}
  </>;
}

type FinanceTab = "overview" | "accounts" | "transactions" | "budget" | "obligations" | "goals" | "reports";
export function FinanceModule({ data, act, openTask }: { data: AppData; act: ActionFn; openTask: (task: Task) => void }) {
  const [tab, setTab] = useState<FinanceTab>("overview");
  const [accountModal, setAccountModal] = useState<FinanceAccount | null | false>(false);
  const [transactionModal, setTransactionModal] = useState(false);
  const [transactionPreset, setTransactionPreset] = useState<{ categoryId: string; expenseOnly: boolean; description?: string } | null>(null);
  const [transactionEdit, setTransactionEdit] = useState<FinanceTransaction | null>(null);
  const [transactionDetailMode, setTransactionDetailMode] = useState(false);
  const [showTransactionFilters, setShowTransactionFilters] = useState(false);
  const [budgetAssignmentModal, setBudgetAssignmentModal] = useState(false);
  const [categoryModal, setCategoryModal] = useState<FinanceCategory | "manager" | "new" | false>(false);
  const [obligationModal, setObligationModal] = useState<FinanceObligation | null | false>(false);
  const [goalModal, setGoalModal] = useState(false);
  const [budgetMonth, setBudgetMonth] = useState(monthKey());
  const f = data.finance;
  const accounts = f.accounts.filter((x) => !x.archived);
  const account = (id: string | null) => f.accounts.find((x) => x.id === id);
  const category = (id: string | null) => f.categories.find((x) => x.id === id);
  const task = (id: string | null) => data.tasks.find((x) => x.id === id);
  const project = (id: string | null) => data.projects.find((x) => x.id === id);
  const openTransactionModal = (preset?: { categoryId: string; expenseOnly: boolean; description?: string }) => { setTransactionPreset(preset || null); setTransactionModal(true); };
  const closeTransactionModal = () => { setTransactionModal(false); setTransactionPreset(null); };
  const remainingIncomeThisMonth = calculateRemainingIncomeForMonth(f.incomeBudgets, monthKey());
  const availableAfterIncome = f.summary.uncommittedMinor + remainingIncomeThisMonth;
  const expensesThisMonth = f.transactions.filter((x) => x.status === "confirmed" && x.occurredOn <= localToday() && x.occurredOn.startsWith(monthKey())).reduce((s, x) => s + (x.type === "expense" ? x.amountMinor + x.feeMinor : x.type === "transfer" ? x.feeMinor : 0), 0);
  const incomeThisMonth = f.transactions.filter((x) => x.type === "income" && x.status === "confirmed" && x.occurredOn <= localToday() && x.occurredOn.startsWith(monthKey())).reduce((s, x) => s + x.amountMinor, 0);
  const exportCsv = () => {
    const quote = (v: unknown) => `"${String(v ?? "").replaceAll('"', '""')}"`;
    const rows = [["Fecha", "Tipo", "Descripción", "Cuenta", "Destino", "Categoría", "Tarea", "Proyecto", "Importe", "Cargo", "Estado"], ...f.transactions.map((x) => [x.occurredOn, names[x.type], x.description, account(x.accountId)?.name || "", account(x.destinationAccountId)?.name || "", category(x.categoryId)?.name || "", task(x.taskId)?.title || "", project(x.projectId)?.name || "", (x.amountMinor / 100).toFixed(2), (x.feeMinor / 100).toFixed(2), x.status])];
    const blob = new Blob(["\uFEFF" + rows.map((r) => r.map(quote).join(",")).join("\n")], { type: "text/csv;charset=utf-8" });
    const a = document.createElement("a"); a.href = URL.createObjectURL(blob); a.download = `vida-en-orden-movimientos-${localToday()}.csv`; a.click(); URL.revokeObjectURL(a.href);
  };
  return <>
    <div className="metrics financeMetrics"><Metric label="Saldo líquido actual" value={money(f.summary.liquidMinor)} help="Efectivo y cuentas; el crédito no se suma" /><Metric label="Comprometido" value={money(f.summary.committedMinor)} help="Sin duplicar presupuesto y obligaciones" /><Metric label="Disponible sin comprometer" value={money(f.summary.uncommittedMinor)} help="Saldo realmente libre" detail={<><span>Después de ingresos</span> {money(availableAfterIncome)}</>} tone={f.summary.uncommittedMinor < 0 ? "dangerMetric" : "successMetric"} /><Metric label="Flujo realizado del mes" value={money(incomeThisMonth - expensesThisMonth)} help={`${money(incomeThisMonth)} ingresado · ${money(expensesThisMonth)} gastado`} /></div>
    <div className="financeRule"><span>Regla de integridad</span><b>El estimado vive en la tarea; el gasto real vive aquí.</b><p>Al vincular una transacción a una tarea o proyecto, el costo se refleja automáticamente en ambos lugares sin contarlo dos veces.</p></div>
    <div className="subnav financeTabs">{(["overview", "accounts", "transactions", "budget", "obligations", "goals", "reports"] as FinanceTab[]).map((x) => <button className={tab === x ? "active" : ""} onClick={() => setTab(x)} key={x}>{({ overview: "Resumen", accounts: "Cuentas", transactions: "Movimientos", budget: "Presupuesto", obligations: "Obligaciones", goals: "Metas", reports: "Reportes" } as Record<string, string>)[x]}</button>)}</div>
    {tab === "overview" && <FinanceOverview data={data} setTab={setTab} openTask={openTask} />}
    {tab === "accounts" && <section className="panel"><div className="panelHead"><div><h2>Cuentas</h2><p className="soft">El saldo inicial parte de una fecha de corte; el banco asociado permite calcular automáticamente las comisiones de transferencia.</p></div><button className="primary" onClick={() => setAccountModal(null)}>＋ Cuenta</button></div>{accounts.length ? <div className="accountGrid">{accounts.map((x) => <article className="accountCard" key={x.id}><span>{x.type === "cash" ? "Efectivo" : x.type === "savings" ? "Ahorros" : x.type === "credit" ? "Crédito disponible · no es efectivo" : "Cuenta bancaria"}</span><b>{x.name}</b>{x.bankName ? <small className="accountBank">{x.bankName}</small> : <small className="accountBank missing">Banco no configurado</small>}<strong>{money(x.balanceMinor)}</strong><small>{x.type === "credit" ? "Disponible inicial" : "Saldo inicial"} {money(x.openingBalanceMinor)} al {dateLabel(x.openingBalanceDate)}</small><div className="accountActions"><button onClick={() => setAccountModal(x)}>Editar</button><button className="textDanger" onClick={() => window.confirm(`¿Archivar ${x.name}?`) && act("finance.account.archive", { id: x.id })}>Archivar</button></div></article>)}</div> : <Empty>Registra al menos una cuenta para comenzar a controlar tus finanzas.</Empty>}</section>}
    {tab === "transactions" && <section className="panel"><div className="panelHead"><div><h2>Movimientos</h2><p className="soft">Las transferencias cambian la ubicación del dinero, pero nunca el patrimonio total.</p></div><div className="buttonRow"><button onClick={exportCsv}>Exportar CSV</button><button className={showTransactionFilters ? "activeFilterButton" : ""} onClick={() => setShowTransactionFilters((open) => !open)} aria-expanded={showTransactionFilters}>Filtrar</button><button className="primary" disabled={!accounts.length} onClick={() => openTransactionModal()}>＋ Movimiento</button></div></div><TransactionTable data={data} act={act} openTask={openTask} onEdit={(transaction) => { setTransactionDetailMode(false); setTransactionEdit(transaction); }} filtersOpen={showTransactionFilters} /></section>}
    {tab === "budget" && <BudgetPanel data={data} act={act} month={budgetMonth} setMonth={setBudgetMonth} newCategory={() => setCategoryModal("new")} manageCategories={() => setCategoryModal("manager")} assignBudget={() => setBudgetAssignmentModal(true)} openTransaction={(transaction) => { setTransactionDetailMode(true); setTransactionEdit(transaction); }} newTransaction={(categoryId, concept) => openTransactionModal({ categoryId, expenseOnly: true, description: concept })} />}
    {tab === "obligations" && <Obligations data={data} act={act} onNew={() => setObligationModal(null)} onEdit={(value) => setObligationModal(value)} />}
    {tab === "goals" && <GoalsPanel data={data} act={act} onNew={() => setGoalModal(true)} />}
    {tab === "reports" && <Reports data={data} exportCsv={exportCsv} />}
    {accountModal !== false && <AccountForm account={accountModal || undefined} act={act} close={() => setAccountModal(false)} />}
    {transactionModal && <TransferTransactionForm data={data} act={act} close={closeTransactionModal} initialCategoryId={transactionPreset?.categoryId || ""} initialDescription={transactionPreset?.description || ""} expenseOnly={transactionPreset?.expenseOnly || false} />}
    {transactionEdit && <TransactionAmountForm data={data} transaction={transactionEdit} accounts={accounts} act={act} showDetails={transactionDetailMode} close={() => { setTransactionEdit(null); setTransactionDetailMode(false); }} />}
    {budgetAssignmentModal && <BudgetAssignmentModal data={data} act={act} month={budgetMonth} close={() => setBudgetAssignmentModal(false)} />}
    {categoryModal === "manager" && <CategoryManager categories={f.categories} data={data} act={act} close={() => setCategoryModal(false)} newCategory={() => setCategoryModal("new")} editCategory={(value) => setCategoryModal(value)} />}
    {categoryModal === "new" && <CategoryForm act={act} close={() => setCategoryModal(false)} />}
    {categoryModal && typeof categoryModal === "object" && <CategoryForm category={categoryModal} act={act} close={() => setCategoryModal("manager")} />}
    {obligationModal !== false && <ObligationForm data={data} obligation={obligationModal || undefined} act={act} close={() => setObligationModal(false)} />}
    {goalModal && <GoalFormModal data={data} act={act} close={() => setGoalModal(false)} />}
  </>;
}

function FinanceOverview({ data, setTab, openTask }: { data: AppData; setTab: (x: FinanceTab) => void; openTask: (task: Task) => void }) {
  const f = data.finance;
  const taskContext = (value: Task) => { const area = data.areas.find((x) => x.id === value.areaId), linkedProject = data.projects.find((x) => x.id === value.projectId); return <span className="summaryContexts">{area && <span className="contextBadge areaContext"><i style={{ background: area.color }} />{area.name}</span>}{linkedProject && <span className="contextBadge projectContext">◇ {linkedProject.name}</span>}</span>; };
  const committed = [
    ["Presupuesto por consumir", f.summary.budgetRemainingMinor, "#2463eb"], ["Reservas para otros meses", f.summary.obligationReservedMinor, "#c24247"],
    ["Metas reservadas", f.summary.goalReservedMinor, "#7c5ce7"], ["Colchón de seguridad", f.summary.safetyBufferMinor, "#21835a"],
  ] as const;
  const max = Math.max(...committed.map((x) => x[1]), 1);
  const upcoming = f.occurrences.filter((x) => x.status !== "paid").slice(0, 5);
  const linked = data.tasks.filter((x) => (f.taskSpend[x.id] || 0) > 0).sort((a, b) => (f.taskSpend[b.id] || 0) - (f.taskSpend[a.id] || 0)).slice(0, 5);
  return <div className="twocol"><div><section className="panel"><div className="panelHead"><h2>Distribución del dinero comprometido</h2><span className="soft">Sin duplicidades</span></div>{committed.map(([label, value, color]) => <div className="commitRow" key={label}><div><span>{label}</span><b>{money(value)}</b></div><div className="bar"><i style={{ width: `${value / max * 100}%`, background: color }} /></div></div>)}</section><section className="panel"><div className="panelHead"><h2>Gastos vinculados a tareas</h2><button onClick={() => setTab("transactions")}>Ver movimientos →</button></div>{linked.length ? linked.map((t) => <button className="linkedCost" key={t.id} onClick={() => openTask(t)}><span>{t.title}<small>Estimado: {legacyMoney(t.estimate)}</small>{taskContext(t)}</span><b>{money(f.taskSpend[t.id])}</b></button>) : <Empty>Cuando vincules un gasto a una tarea, aparecerá aquí.</Empty>}</section></div><div><section className="panel"><div className="panelHead"><h2>Próximos compromisos</h2><button onClick={() => setTab("obligations")}>Gestionar →</button></div>{upcoming.length ? upcoming.map((x) => { const o = f.obligations.find((z) => z.id === x.obligationId); return <div className="dueRow" key={x.id}><span><b>{o?.title || "Compromiso"}</b><small>{dateLabel(x.dueDate)} · {x.status === "partial" ? "Pago parcial" : "Pendiente"}</small></span><strong>{money(x.expectedMinor - x.paidMinor)}</strong></div>; }) : <Empty>No hay compromisos pendientes.</Empty>}</section><section className="panel"><div className="panelHead"><h2>Proyección</h2><button onClick={() => setTab("reports")}>Abrir reporte →</button></div>{f.cashflow.length ? f.cashflow.slice(0, 6).map((x) => <div className="cashPoint" key={x.date}><span>{dateLabel(x.date)}</span><b className={x.changeMinor < 0 ? "negative" : "positive"}>{x.changeMinor > 0 ? "+" : ""}{money(x.changeMinor)}</b><strong>{money(x.balanceMinor)}</strong></div>) : <p className="soft">Registra obligaciones o movimientos futuros para proyectar tu saldo.</p>}</section></div></div>;
}

function TransactionAmountForm({ data, transaction, accounts, act, close, showDetails = false }: { data: AppData; transaction: FinanceTransaction; accounts: FinanceAccount[]; act: ActionFn; close: () => void; showDetails?: boolean }) {
  const [amount, setAmount] = useState(String(transaction.amountMinor / 100));
  const [accountId, setAccountId] = useState(transaction.accountId);
  const [categoryId, setCategoryId] = useState(transaction.categoryId || "");
  const [paymentMethod, setPaymentMethod] = useState(transaction.paymentMethod || "standard");
  const [counterpartyBank, setCounterpartyBank] = useState(transaction.counterpartyBank || "");
  const [transferMode, setTransferMode] = useState(transaction.transferMode || "ach");
  const [description, setDescription] = useState(transaction.description || "");
  const source = accounts.find((account) => account.id === accountId);
  const destination = data.finance.accounts.find((account) => account.id === transaction.destinationAccountId);
  const expenseTransfer = transaction.type === "expense" && paymentMethod === "transfer";
  const targetBank = transaction.type === "transfer" ? destination?.bankName || "" : expenseTransfer ? counterpartyBank : "";
  const sameBank = !!source?.bankName && !!targetBank && normalizeBankName(source.bankName) === normalizeBankName(targetBank);
  const effectiveTransferMode = sameBank ? "same_bank" : (["ach", "lbtr"].includes(transferMode) ? transferMode : "ach");
  const fee = (transaction.type === "transfer" || expenseTransfer) && source && targetBank
    ? transferFeeFor(effectiveTransferMode, source.bankName, targetBank, minor(amount), data.finance.settings)
    : 0;
  const categories = data.finance.categories.filter((category) => category.kind === (transaction.type === "income" ? "income" : "expense"));
  const bankNames = [...new Set([...accounts.map((account) => account.bankName), ...Object.keys(data.finance.settings.transferBankFees || {})].filter(Boolean))].sort();
  const detailAccount = data.finance.accounts.find((account) => account.id === transaction.accountId)?.name || "Cuenta";
  const detailDestination = data.finance.accounts.find((account) => account.id === transaction.destinationAccountId)?.name || "No aplica";
  const detailCategory = data.finance.categories.find((category) => category.id === transaction.categoryId)?.name || "Sin categoría";
  const detailTask = data.tasks.find((task) => task.id === transaction.taskId)?.title;
  const detailProject = data.projects.find((project) => project.id === transaction.projectId)?.name;
  const detailGoal = data.finance.goals.find((goal) => goal.id === transaction.goalId)?.title;
  const detailStatus = transaction.status === "voided" ? "Anulado" : transaction.occurredOn > localToday() ? "Futuro" : "Confirmado";
  const detailLinks = [detailTask, detailProject, detailGoal, transaction.obligationOccurrenceId ? "Obligación" : ""].filter(Boolean).join(" · ") || "Sin vínculos";
  const submit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    await act("finance.transaction.update_amount", { id: transaction.id, amountMinor: minor(amount), accountId, categoryId: transaction.type === "income" || transaction.type === "expense" ? categoryId : null, paymentMethod: transaction.type === "expense" ? paymentMethod : transaction.paymentMethod, counterpartyBank: expenseTransfer ? counterpartyBank : transaction.counterpartyBank, transferMode: transaction.type === "transfer" || expenseTransfer ? effectiveTransferMode : null, description });
    close();
  };
  return <Modal title={showDetails ? "Detalle del gasto" : "Editar movimiento"} onClose={close} wide><form className="form" onSubmit={submit}>{showDetails && <section className="transactionReadOnly" aria-label="Detalles del movimiento"><div className="transactionReadOnlyHead"><div><h3>Datos del movimiento</h3><p>Estos datos se muestran en solo vista. Los campos editables aparecen debajo.</p></div><span className="status">{detailStatus}</span></div><div className="transactionReadOnlyGrid"><div><span>Tipo</span><b>{names[transaction.type]}</b></div><div><span>Fecha</span><b>{dateLabel(transaction.occurredOn)}</b></div><div><span>Cuenta de origen</span><b>{detailAccount}</b></div><div><span>Cuenta destino</span><b>{detailDestination}</b></div><div><span>Categoría actual</span><b>{detailCategory}</b></div><div><span>Cargo registrado</span><b>{money(transaction.feeMinor)}</b></div><div><span>Vínculos</span><b>{detailLinks}</b></div><div><span>Registrado</span><b>{new Date(transaction.createdAt).toLocaleString("es-DO", { dateStyle: "medium", timeStyle: "short" })}</b></div><div><span>Identificador</span><b className="detailId">{transaction.id}</b></div></div></section>}<div className="infoBox"><b>{transaction.description || names[transaction.type]}</b><span>Se conservarán la fecha, los vínculos y las reservas relacionadas. Si es una transferencia, la comisión se recalculará con la nueva configuración.</span></div><div className="formgrid"><label>Cuenta de origen*<select required value={accountId} onChange={(event) => setAccountId(event.target.value)}>{accounts.map((account) => <option value={account.id} key={account.id}>{account.name}{account.bankName ? ` · ${account.bankName}` : ""}</option>)}</select></label><label>Importe RD$*<input required autoFocus type="number" min="0.01" step="0.01" value={amount} onChange={(event) => setAmount(event.target.value)} /></label></div>{(transaction.type === "income" || transaction.type === "expense") && <label>Categoría<select value={categoryId} onChange={(event) => setCategoryId(event.target.value)}><option value="">Sin categoría</option>{categories.map((category) => <option value={category.id} key={category.id}>{category.name}</option>)}</select></label>}{transaction.type === "expense" && <div className="formgrid"><label>Método de pago<select value={paymentMethod} onChange={(event) => setPaymentMethod(event.target.value)}><option value="standard">Efectivo, tarjeta u otro</option><option value="transfer">Transferencia bancaria</option></select></label>{expenseTransfer && <label>Banco destino*<input required list="edit-expense-bank-list" value={counterpartyBank} onChange={(event) => setCounterpartyBank(event.target.value)} placeholder="Banco del destinatario" /><datalist id="edit-expense-bank-list">{bankNames.map((bank) => <option value={bank} key={bank} />)}</datalist></label>}</div>}{(transaction.type === "transfer" || expenseTransfer) && <div className="formgrid"><label>Modalidad<select value={effectiveTransferMode} disabled={sameBank} onChange={(event) => setTransferMode(event.target.value)}>{sameBank ? <option value="same_bank">Mismo banco</option> : <><option value="ach">ACH (normal)</option><option value="lbtr">LBTR / inmediata</option></>}</select></label><div className="transferPreview"><span>Comisión automática</span><b>{money(fee)}</b><small>{sameBank ? "Tarifa configurada para cuentas del mismo banco." : "Tarifa según el banco destino y la modalidad."}</small></div></div>}{(transaction.type === "transfer" || expenseTransfer) && fee > 0 && <div className="infoBox"><b>Total que saldrá de la cuenta: {money(minor(amount) + fee)}</b><span>La comisión se conservará como gasto bancario y se recalculará al guardar.</span></div>}<ConceptInput concepts={data.finance.concepts} name="description" value={description} onChange={(event) => setDescription(event.target.value)} required={transaction.type !== "transfer"} placeholder="Descripción del movimiento" />{transaction.obligationOccurrenceId && <p className="soft">Este movimiento está vinculado a una obligación; también se actualizará el importe pagado de ese vencimiento.</p>}{transaction.goalId && transaction.goalReservationConsumedMinor > 0 && <p className="soft">El consumo de la reserva de la meta se ajustará al nuevo importe.</p>}<div className="formActions"><button type="button" onClick={close}>Cancelar</button><button className="primary">Guardar cambios</button></div></form></Modal>;
}

function TransactionTable({ data, act, openTask, onEdit, filtersOpen }: { data: AppData; act: ActionFn; openTask: (task: Task) => void; onEdit: (transaction: FinanceTransaction) => void; filtersOpen: boolean }) {
  const f = data.finance, account = (id: string | null) => f.accounts.find((x) => x.id === id)?.name || "Cuenta", category = (id: string | null) => f.categories.find((x) => x.id === id)?.name || "Sin categoría", goal = (id: string | null) => f.goals.find((x) => x.id === id)?.title;
  const initialFilters: MovementFilters = { query: "", dateFrom: "", dateTo: "", accountId: "", direction: "all" };
  const [filters, setFilters] = useState<MovementFilters>(initialFilters);
  const filteredTransactions = f.transactions.filter((transaction) => matchesMovementFilters(transaction, filters, {
    typeName: names[transaction.type],
    accountName: f.accounts.find((item) => item.id === transaction.accountId)?.name,
    destinationAccountName: f.accounts.find((item) => item.id === transaction.destinationAccountId)?.name,
    categoryName: f.categories.find((item) => item.id === transaction.categoryId)?.name,
    taskName: data.tasks.find((item) => item.id === transaction.taskId)?.title,
    projectName: data.projects.find((item) => item.id === transaction.projectId)?.name,
    goalName: f.goals.find((item) => item.id === transaction.goalId)?.title,
    amountFormatted: (transaction.amountMinor / 100).toFixed(2),
    feeFormatted: (transaction.feeMinor / 100).toFixed(2),
  }));
  const activeFilterCount = [filters.query, filters.dateFrom, filters.dateTo, filters.accountId, filters.direction !== "all" ? filters.direction : ""].filter(Boolean).length;
  const setFilter = <K extends keyof MovementFilters>(key: K, value: MovementFilters[K]) => setFilters((current) => ({ ...current, [key]: value }));
  const accounts = f.accounts.filter((item) => !item.archived);
  return <>
    {filtersOpen && <div className="movementFilters" role="region" aria-label="Filtros de movimientos">
      <div className="movementFilterHead"><div><b>Filtrar movimientos</b><p>Busca en todos los campos o combina los filtros para acotar la lista.</p></div><span className="filterCount">{filteredTransactions.length} de {f.transactions.length}</span></div>
      <div className="movementFilterGrid">
        <label className="movementFilterSearch">Texto libre<input type="search" autoFocus value={filters.query} onChange={(event) => setFilter("query", event.target.value)} placeholder="Número, concepto, cuenta, categoría…" /></label>
        <label>Desde<input type="date" value={filters.dateFrom} onChange={(event) => setFilter("dateFrom", event.target.value)} /></label>
        <label>Hasta<input type="date" value={filters.dateTo} onChange={(event) => setFilter("dateTo", event.target.value)} /></label>
        <label>Cuenta<select value={filters.accountId} onChange={(event) => setFilter("accountId", event.target.value)}><option value="">Todas las cuentas</option>{accounts.map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</select></label>
        <label>Movimiento<select value={filters.direction} onChange={(event) => setFilter("direction", event.target.value as MovementFilters["direction"])}><option value="all">Débito y crédito</option><option value="debit">Sólo débito</option><option value="credit">Sólo crédito</option></select></label>
      </div>
      <div className="movementFilterFooter"><span className="filterHint">Una sola fecha: usa Desde o Hasta. Para un rango, completa ambas.</span><button type="button" onClick={() => setFilters(initialFilters)} disabled={!activeFilterCount}>Limpiar filtros{activeFilterCount ? ` · ${activeFilterCount}` : ""}</button></div>
    </div>}
    {!f.transactions.length ? <Empty>No hay movimientos registrados.</Empty> : !filteredTransactions.length ? <Empty>No hay movimientos que coincidan con estos filtros.</Empty> : <div className="tableWrap"><table><thead><tr><th>Fecha</th><th>Concepto</th><th>Cuenta</th><th>Vínculo</th><th>Importe</th><th /></tr></thead><tbody>{filteredTransactions.map((x) => { const t = data.tasks.find((z) => z.id === x.taskId), p = data.projects.find((z) => z.id === x.projectId); return <tr className={x.status === "voided" ? "voided" : ""} key={x.id}><td>{dateLabel(x.occurredOn)}</td><td><b>{x.description || names[x.type]}</b><small className="tableSub">{names[x.type]}{x.paymentMethod === "transfer" ? " · Pagado por transferencia" : ""}{x.transferMode ? ` · ${x.transferMode === "same_bank" ? "Mismo banco" : x.transferMode === "lbtr" ? "LBTR / inmediata" : "ACH"}` : ""} · {category(x.categoryId)}</small></td><td>{account(x.accountId)}{x.destinationAccountId && <small className="tableSub">→ {account(x.destinationAccountId)}</small>}{x.counterpartyBank && !x.destinationAccountId && <small className="tableSub">→ {x.counterpartyBank}</small>}</td><td>{t ? <button className="lineTitle" onClick={() => openTask(t)}>{t.title}</button> : p?.name || goal(x.goalId) || "—"}{x.goalReservationConsumedMinor > 0 && <small className="tableSub positive">Reserva usada: {money(x.goalReservationConsumedMinor)}</small>}</td><td><b className={x.type === "income" ? "positive" : x.type === "expense" || x.feeMinor ? "negative" : ""}>{x.type === "income" ? "+" : x.type === "expense" ? "−" : ""}{money(x.amountMinor)}</b>{x.feeMinor > 0 && <small className="tableSub negative">Cargo automático: {money(x.feeMinor)}</small>}{x.occurredOn > localToday() && <small className="tableSub">Futuro</small>}</td><td>{x.status !== "voided" && <div className="buttonRow"><button title="Editar importe" onClick={() => onEdit(x)}>Editar</button><button className="iconDanger" title="Anular" onClick={() => window.confirm("¿Anular este movimiento? Se conservará en la auditoría y restaurará cualquier reserva de meta utilizada.") && act("finance.transaction.void", { id: x.id, reason: "Anulado desde la aplicación" })}>×</button></div>}</td></tr>; })}</tbody></table></div>}
  </>;
}

function AccountForm({ account, act, close }: { account?: FinanceAccount; act: ActionFn; close: () => void }) {
  const [f, setF] = useState({ name: account?.name || "", type: account?.type || "bank", bankName: account?.bankName || "", openingBalance: account ? String(account.openingBalanceMinor / 100) : "", openingBalanceDate: account?.openingBalanceDate || localToday() });
  const editing = !!account;
  return <Modal title={editing ? "Editar cuenta" : "Nueva cuenta"} onClose={close}><form className="form" onSubmit={async (e) => { e.preventDefault(); await act(editing ? "finance.account.update" : "finance.account.create", { id: account?.id, name: f.name, type: f.type, bankName: f.bankName, openingBalanceMinor: minor(f.openingBalance), openingBalanceDate: f.openingBalanceDate }); close(); }}><label>Nombre*<input required autoFocus value={f.name} onChange={(e) => setF({ ...f, name: e.target.value })} /></label><label>Banco o entidad financiera{f.type === "cash" ? " (opcional)" : "*"}<input required={f.type !== "cash"} value={f.bankName} onChange={(e) => setF({ ...f, bankName: e.target.value })} placeholder="Ej. Banco Popular" /></label><label>Tipo<select value={f.type} onChange={(e) => setF({ ...f, type: e.target.value })}><option value="bank">Cuenta bancaria</option><option value="cash">Efectivo</option><option value="savings">Ahorros</option><option value="credit">Crédito</option></select></label>{!editing && <div className="formgrid"><label>Saldo inicial RD$<input required type="number" min="0" step="0.01" value={f.openingBalance} onChange={(e) => setF({ ...f, openingBalance: e.target.value })} /></label><label>Fecha de corte<input required type="date" value={f.openingBalanceDate} onChange={(e) => setF({ ...f, openingBalanceDate: e.target.value })} /></label></div>}{editing ? <p className="soft">El saldo inicial y la fecha de corte se conservan para no alterar el historial. Solo se actualizan los datos identificativos.</p> : <p className="soft">El banco asociado se usa para clasificar transferencias al mismo banco o interbancarias.</p>}<div className="formActions"><button type="button" onClick={close}>Cancelar</button><button className="primary">{editing ? "Guardar cambios" : "Crear cuenta"}</button></div></form></Modal>;
}

function TransactionForm({ data, act, close }: { data: AppData; act: ActionFn; close: () => void }) {
  const accounts = data.finance.accounts.filter((x) => !x.archived);
  const [f, setF] = useState({ type: "expense", accountId: accounts[0]?.id || "", destinationAccountId: "", amount: "", occurredOn: localToday(), categoryId: "", taskId: "", projectId: "", description: "" });
  const change = (field: keyof typeof f, next: string) => setF((current) => ({ ...current, [field]: next }));
  const categories = data.finance.categories.filter((x) => x.kind === (f.type === "income" ? "income" : "expense"));
  const selectedTask = data.tasks.find((x) => x.id === f.taskId);
  return <Modal title="Nuevo movimiento" onClose={close} wide><form className="form" onSubmit={async (e) => { e.preventDefault(); const fields=Object.fromEntries(new FormData(e.currentTarget).entries()); await act("finance.transaction.create", { ...fields, type:f.type, amountMinor: minor(String(fields.amount || "0")), status: "confirmed" }); close(); }}><div className="typeChooser">{["expense", "income", "transfer", "adjustment"].map((x) => <button type="button" className={f.type === x ? "active" : ""} onClick={() => setF((current)=>({ ...current, type: x, categoryId: "", destinationAccountId: "" }))} key={x}>{names[x]}</button>)}</div><div className="formgrid"><label>Cuenta de origen*<select name="accountId" required value={f.accountId} onChange={(e) => change("accountId", e.target.value)}>{accounts.map((x) => <option value={x.id} key={x.id}>{x.name} · {money(x.balanceMinor)}</option>)}</select></label>{f.type === "transfer" ? <label>Cuenta destino*<select name="destinationAccountId" required value={f.destinationAccountId} onChange={(e) => change("destinationAccountId", e.target.value)}><option value="">Selecciona…</option>{accounts.filter((x) => x.id !== f.accountId).map((x) => <option value={x.id} key={x.id}>{x.name}</option>)}</select></label> : <label>Categoría<select name="categoryId" value={f.categoryId} onChange={(e) => change("categoryId", e.target.value)}><option value="">Sin categoría</option>{categories.map((x) => <option value={x.id} key={x.id}>{x.name}</option>)}</select></label>}</div><div className="formgrid"><label>Importe RD$*<input name="amount" required type="number" min="0.01" step="0.01" value={f.amount} onChange={(e) => change("amount", e.target.value)} /></label><label>Fecha*<input name="occurredOn" required type="date" value={f.occurredOn} onInput={(e)=>change("occurredOn",(e.target as HTMLInputElement).value)} onChange={(e) => change("occurredOn", e.target.value)} /></label></div><label>Concepto<input name="description" required={f.type !== "transfer"} value={f.description} onChange={(e) => change("description", e.target.value)} placeholder={f.type === "expense" ? "¿En qué se gastó?" : "Descripción del movimiento"} /></label>{f.type === "expense" && <><div className="formgrid"><label>Vincular a tarea<select name="taskId" value={f.taskId} onChange={(e) => { const id=e.target.value; setF((current)=>({ ...current, taskId:id, projectId:id ? data.tasks.find((t) => t.id === id)?.projectId || current.projectId : current.projectId })); }}><option value="">Sin tarea</option>{data.tasks.filter((x) => !x.archived).map((x) => <option value={x.id} key={x.id}>{x.title}</option>)}</select></label><label>Vincular a proyecto<select name="projectId" value={f.projectId} onChange={(e) => change("projectId", e.target.value)}><option value="">Sin proyecto</option>{data.projects.map((x) => <option value={x.id} key={x.id}>{x.name}</option>)}</select></label></div>{selectedTask && <div className="infoBox"><b>{selectedTask.title}</b><span>Estimado: {legacyMoney(selectedTask.estimate)} · Gastado confirmado: {money(data.finance.taskSpend[selectedTask.id] || 0)}</span><small>Este movimiento actualizará el gasto real de la tarea; no crea una segunda cifra.</small></div>}</>} {f.occurredOn > localToday() && <div className="warningBox"><b>Movimiento futuro</b><span>Se guardará para la proyección, pero no aumentará ni reducirá el saldo disponible de hoy.</span></div>}<div className="formActions"><button type="button" onClick={close}>Cancelar</button><button className="primary">Registrar movimiento</button></div></form></Modal>;
}

