function BudgetForm({ categories, initialMonth, budget, act, close }: { categories: FinanceCategory[]; initialMonth: string; budget?: FinanceBudget; act: ActionFn; close: () => void }) {
  const editing = !!budget;
  const [f, setF] = useState({ categoryId: budget?.categoryId || categories[0]?.id || "", assigned: budget ? String(budget.manualAssignedMinor / 100) : "", month: budget?.month || initialMonth });
  const submit = async (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); await act(editing ? "finance.budget.update" : "finance.budget.set", { id: budget?.id, categoryId: f.categoryId, month: f.month, assignedMinor: minor(f.assigned) }); close(); };
  return <Modal title={editing ? "Editar asignación presupuestaria" : "Asignar presupuesto adicional"} onClose={close}><form className="form" onSubmit={submit}><label>Mes<input type="month" required value={f.month} onChange={(e) => setF({ ...f, month: e.target.value })} /></label><label>Categoría<select required value={f.categoryId} onChange={(e) => setF({ ...f, categoryId: e.target.value })}>{categories.map((x) => <option value={x.id} key={x.id}>{x.name}</option>)}</select></label><label>Tope total deseado RD$<input required type="number" min="0" step="0.01" value={f.assigned} onChange={(e) => setF({ ...f, assigned: e.target.value })} /></label><div className="infoBox"><b>No se suma dos veces</b><span>Si esta categoría ya contiene obligaciones, el sistema conservará el mayor valor entre este tope y la provisión automática. Eliminar esta asignación no elimina la obligación.</span></div><div className="formActions"><button type="button" onClick={close}>Cancelar</button><button className="primary">{editing ? "Guardar cambios" : "Guardar asignación"}</button></div></form></Modal>;
}

function CategoryManager({ categories, data, act, close, newCategory, editCategory }: { categories: FinanceCategory[]; data: AppData; act: ActionFn; close: () => void; newCategory: () => void; editCategory: (category: FinanceCategory) => void }) {
  const usage = (id: string) => {
    const transactions = data.finance.transactions.filter((x) => x.categoryId === id).length;
    const budgets = data.finance.budgets.filter((x) => x.categoryId === id && !x.id.startsWith("automatic-")).length;
    const obligations = data.finance.obligations.filter((x) => x.categoryId === id).length;
    const goals = data.finance.goals.filter((x) => x.categoryId === id).length;
    return { transactions, budgets, obligations, goals, total: transactions + budgets + obligations + goals };
  };
  const renderGroup = (kind: "expense" | "income", label: string) => {
    const rows = categories.filter((x) => x.kind === kind);
    return <section className="categoryManagerGroup" key={kind}><h3>{label}</h3>{rows.length ? rows.map((category) => { const counts = usage(category.id); const protectedCategory = category.name === "Comisiones bancarias" && category.kind === "expense"; return <div className="categoryManagerRow" key={category.id}><i style={{ background: category.color }} /><div><b>{category.name}</b><small>{counts.total ? `${counts.total} vínculo${counts.total === 1 ? "" : "s"} · ` : "Sin vínculos · "}{counts.transactions} movimiento{counts.transactions === 1 ? "" : "s"}, {counts.budgets} presupuesto{counts.budgets === 1 ? "" : "s"}</small></div><div className="categoryManagerActions"><button onClick={() => editCategory(category)}>Editar</button><button className="textDanger" disabled={protectedCategory || counts.total > 0} title={protectedCategory ? "Categoría necesaria para las comisiones automáticas" : counts.total > 0 ? "Reasigna primero sus vínculos" : "Eliminar categoría"} onClick={async () => { if (!window.confirm(`¿Eliminar la categoría “${category.name}”?`)) return; try { await act("finance.category.delete", { id: category.id }); } catch { /* El banner global muestra el motivo. */ } }}>Eliminar</button></div></div>; }) : <p className="soft">No hay categorías de este tipo.</p>}</section>;
  };
  return <Modal title="Gestionar categorías" onClose={close} wide><p className="soft">Editar conserva los movimientos, obligaciones y presupuestos vinculados. Las categorías con datos en uso no se pueden eliminar para evitar registros huérfanos.</p>{renderGroup("expense", "Gastos")}{renderGroup("income", "Ingresos")}<div className="formActions"><button onClick={newCategory}>＋ Nueva categoría</button><button className="primary" onClick={close}>Listo</button></div></Modal>;
}

function CategoryForm({ category, act, close }: { category?: FinanceCategory; act: ActionFn; close: () => void }) {
  const [name, setName] = useState(category?.name || ""), [kind, setKind] = useState(category?.kind || "expense"), [color, setColor] = useState(category?.color || "#2463eb");
  const editing = !!category;
  return <Modal title={editing ? "Editar categoría" : "Nueva categoría"} onClose={close}><form className="form" onSubmit={async (e) => { e.preventDefault(); await act(editing ? "finance.category.update" : "finance.category.create", { id: category?.id, name, kind, color }); close(); }}><label>Nombre*<input required autoFocus value={name} onChange={(e) => setName(e.target.value)} /></label><label>Tipo<select value={kind} onChange={(e) => setKind(e.target.value)}><option value="expense">Gasto</option><option value="income">Ingreso</option></select></label>{editing && <p className="soft">Si la categoría ya tiene movimientos, presupuestos, obligaciones o metas, no podrás cambiar su tipo; el nombre y el color sí se pueden actualizar.</p>}<label>Color<input type="color" value={color} onChange={(e) => setColor(e.target.value)} /></label><div className="formActions"><button type="button" onClick={close}>Cancelar</button><button className="primary">{editing ? "Guardar cambios" : "Crear categoría"}</button></div></form></Modal>;
}

function Obligations({ data, act, onNew, onEdit }: { data: AppData; act: ActionFn; onNew: () => void; onEdit: (value: FinanceObligation) => void }) {
  const f = data.finance;
  return <section className="panel"><div className="panelHead"><div><h2>Obligaciones y recurrencias</h2><p className="soft">Los gastos recurrentes crean provisión presupuestaria y los ingresos recurrentes aparecen como ingresos previstos del mes.</p></div><button className="primary" onClick={onNew}>＋ Obligación</button></div>{f.occurrences.length ? f.occurrences.map((x) => { const o = f.obligations.find((z) => z.id === x.obligationId), c = f.categories.find((z) => z.id === o?.categoryId), frequency = o?.frequency === "once" ? "única" : o?.frequency === "weekly" ? "semanal" : o?.frequency === "yearly" ? "anual" : "mensual"; return <div className="obligationRow" key={x.id}><div className={`obligationIcon ${o?.kind}`}>{o?.kind === "income" ? "↗" : "↘"}</div><span><b>{o?.title || "Obligación"}</b><small>{dateLabel(x.dueDate)} · {frequency}{c ? ` · ${c.name}` : ""}</small>{o?.kind === "expense" && <small>Incluida automáticamente en el presupuesto de {new Date(`${x.dueDate.slice(0, 7)}-01T12:00:00`).toLocaleDateString("es-DO", { month: "long", year: "numeric" })}</small>}{o?.kind === "income" && <small>Incluida automáticamente como ingreso previsto del mes</small>}</span><strong>{money(x.expectedMinor - x.paidMinor)}<small>{x.status === "paid" ? "Pagada" : x.status === "partial" ? "Parcial" : "Pendiente"}</small></strong><button onClick={() => o && onEdit(o)}>Editar</button>{x.status !== "paid" && <PayOccurrence data={data} occurrence={x} obligation={o} accounts={f.accounts.filter((a) => !a.archived)} act={act} />}</div>; }) : <Empty>No hay obligaciones ni ingresos esperados.</Empty>}</section>;
}

function PayOccurrence({ data, occurrence, obligation, accounts, act }: { data: AppData; occurrence: FinanceOccurrence; obligation?: FinanceObligation; accounts: FinanceAccount[]; act: ActionFn }) {
  const [open, setOpen] = useState(false);
  if (!obligation) return null;
  return <>{!open ? <button onClick={() => setOpen(true)}>{obligation.kind === "income" ? "Registrar cobro" : "Registrar pago"}</button> : <ObligationPaymentModal data={data} occurrence={occurrence} obligation={obligation} accounts={accounts} act={act} close={() => setOpen(false)} />}</>;
}

function ObligationPaymentModal({ data, occurrence, obligation, accounts, act, close }: { data: AppData; occurrence: FinanceOccurrence; obligation: FinanceObligation; accounts: FinanceAccount[]; act: ActionFn; close: () => void }) {
  const remainingMinor = Math.max(0, occurrence.expectedMinor - occurrence.paidMinor);
  const expense = obligation.kind === "expense";
  const categoryName = data.finance.categories.find((item) => item.id === obligation.categoryId)?.name || "Sin categoría";
  const [amount, setAmount] = useState(String(remainingMinor / 100));
  const [accountId, setAccountId] = useState(obligation.accountId || accounts[0]?.id || "");
  const [occurredOn, setOccurredOn] = useState(localToday());
  const [description, setDescription] = useState(obligation.concept || obligation.title);
  const [paymentMethod, setPaymentMethod] = useState("standard");
  const [counterpartyBank, setCounterpartyBank] = useState("");
  const [transferMode, setTransferMode] = useState("same_bank");
  const [taskId, setTaskId] = useState("");
  const [projectId, setProjectId] = useState("");
  const source = accounts.find((account) => account.id === accountId);
  const targetBank = expense && paymentMethod === "transfer" ? counterpartyBank : "";
  const sameBank = !!source?.bankName && !!targetBank && normalizeBankName(source.bankName) === normalizeBankName(targetBank);
  const fee = expense && paymentMethod === "transfer" && source && targetBank ? transferFeeFor(sameBank ? "same_bank" : transferMode, source.bankName, targetBank, minor(amount), data.finance.settings) : 0;
  const bankNames = [...new Set([...accounts.map((account) => account.bankName), ...Object.keys(data.finance.settings.transferBankFees || {})].filter(Boolean))].sort();
  const submit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    await act("finance.obligation.pay", { occurrenceId: occurrence.id, accountId, amountMinor: minor(amount), occurredOn, description, paymentMethod: expense ? paymentMethod : "standard", counterpartyBank: expense ? counterpartyBank : "", transferMode: expense && paymentMethod === "transfer" ? (sameBank ? "same_bank" : transferMode) : null, taskId: expense ? taskId : "", projectId: expense ? projectId : "" });
    close();
  };
  return <Modal title={expense ? "Registrar pago" : "Registrar cobro"} onClose={close} wide><form className="form" onSubmit={submit}><div className="infoBox"><b>{obligation.title}</b><span>{expense ? "Gasto" : "Ingreso"} · Vencimiento {dateLabel(occurrence.dueDate)} · Pendiente {money(remainingMinor)}</span><small>{expense ? `Categoría: ${categoryName}. La obligación seguirá vinculada al movimiento.` : "El cobro quedará vinculado a esta ocurrencia y actualizará su estado."}</small></div><div className="formgrid"><label>Cuenta de origen*<select required value={accountId} onChange={(event) => setAccountId(event.target.value)}>{accounts.map((account) => <option value={account.id} key={account.id}>{account.name}{account.bankName ? ` · ${account.bankName}` : ""} · {money(account.balanceMinor)}</option>)}</select></label><label>Importe RD$*<input required type="number" min="0.01" max={remainingMinor / 100} step="0.01" value={amount} onChange={(event) => setAmount(event.target.value)} /></label></div><label>Fecha del {expense ? "pago" : "cobro"}*<input required type="date" max={localToday()} value={occurredOn} onChange={(event) => setOccurredOn(event.target.value)} /></label>{expense && <><div className="formgrid"><label>Método de pago<select value={paymentMethod} onChange={(event) => setPaymentMethod(event.target.value)}><option value="standard">Efectivo, tarjeta u otro</option><option value="transfer">Transferencia bancaria</option></select></label>{paymentMethod === "transfer" && <label>Banco destino*<input required list="obligation-payment-bank-list" value={counterpartyBank} onChange={(event) => setCounterpartyBank(event.target.value)} placeholder="Banco del destinatario" /><datalist id="obligation-payment-bank-list">{bankNames.map((bank) => <option value={bank} key={bank} />)}</datalist></label>}</div>{paymentMethod === "transfer" && <div className="formgrid"><label>Modalidad<select value={sameBank ? "same_bank" : transferMode} disabled={sameBank} onChange={(event) => setTransferMode(event.target.value)}>{sameBank ? <option value="same_bank">Mismo banco</option> : <><option value="ach">ACH (normal)</option><option value="lbtr">LBTR / inmediata</option></>}</select></label><div className="transferPreview"><span>Comisión automática</span><b>{money(fee)}</b><small>{sameBank ? "Tarifa configurada para cuentas del mismo banco." : "Tarifa según el banco destino y la modalidad."}</small></div></div>}{paymentMethod === "transfer" && fee > 0 && <div className="infoBox"><b>Total que saldrá de la cuenta: {money(minor(amount) + fee)}</b><span>La comisión se registrará como gasto bancario separado.</span></div>}</>}<ConceptInput concepts={data.finance.concepts} name="obligationPaymentDescription" value={description} onChange={(event) => setDescription(event.target.value)} required placeholder={expense ? "¿En qué se gastó?" : "Descripción del ingreso"} />{expense && <div className="formgrid"><label>Vincular a tarea<select value={taskId} onChange={(event) => setTaskId(event.target.value)}><option value="">Sin tarea</option>{data.tasks.filter((item) => !item.archived).map((item) => <option value={item.id} key={item.id}>{item.title}</option>)}</select></label><label>Vincular a proyecto<select value={projectId} onChange={(event) => setProjectId(event.target.value)}><option value="">Sin proyecto</option>{data.projects.map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</select></label></div>}<div className="formActions"><button type="button" onClick={close}>Cancelar</button><button className="primary">{expense ? "Registrar pago" : "Registrar cobro"}</button></div></form></Modal>;
}

function ObligationForm({ data, obligation, act, close }: { data: AppData; obligation?: FinanceObligation; act: ActionFn; close: () => void }) {
  const accounts = data.finance.accounts.filter((x) => !x.archived);
  const expenseCategories = data.finance.categories.filter((x) => x.kind === "expense");
  const initialCategory = obligation?.categoryId || (obligation?.kind === "income" ? "" : expenseCategories[0]?.id || "");
  const [f, setF] = useState({ title: obligation?.title || "", concept: obligation?.concept || "", kind: obligation?.kind || "expense", amount: obligation ? String(obligation.expectedAmountMinor / 100) : "", reserved: obligation ? String(obligation.reservedMinor / 100) : "", accountId: obligation?.accountId || "", categoryId: initialCategory, frequency: obligation?.frequency || "monthly", nextDueDate: obligation?.nextDueDate || localToday() });
  const editing = !!obligation;
  const cats = data.finance.categories.filter((x) => x.kind === f.kind);
  const submit = async (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); await act(editing ? "finance.obligation.update" : "finance.obligation.create", { id: obligation?.id, ...f, expectedAmountMinor: minor(f.amount), reservedMinor: f.kind === "expense" ? minor(f.reserved) : 0 }); close(); };
  return <Modal title={editing ? "Editar obligación" : "Nueva obligación"} onClose={close}><form className="form" onSubmit={submit}><label>Nombre*<input required autoFocus value={f.title} onChange={(e) => setF({ ...f, title: e.target.value })} /></label><ConceptInput concepts={data.finance.concepts} name="concept" value={f.concept} onChange={(e) => setF({ ...f, concept: e.target.value })} placeholder="Ej. Electricidad, salario, alquiler…" /><div className="formgrid"><label>Tipo<select value={f.kind} onChange={(e) => setF({ ...f, kind: e.target.value, reserved: "", categoryId: e.target.value === "expense" ? expenseCategories[0]?.id || "" : "" })}><option value="expense">Pago u obligación</option><option value="income">Ingreso esperado</option></select></label><label>Frecuencia<select value={f.frequency} onChange={(e) => setF({ ...f, frequency: e.target.value })}><option value="once">Una sola vez</option><option value="weekly">Semanal</option><option value="monthly">Mensual</option><option value="yearly">Anual</option></select></label></div><div className="formgrid"><label>Importe esperado RD$<input required type="number" min="0.01" step="0.01" value={f.amount} onChange={(e) => setF({ ...f, amount: e.target.value })} /></label>{f.kind === "expense" && <label>Ya reservado RD$<input type="number" min="0" step="0.01" max={f.amount || undefined} value={f.reserved} onChange={(e) => setF({ ...f, reserved: e.target.value })} /></label>}</div><label>Vencimiento<input required type="date" value={f.nextDueDate} onChange={(e) => setF({ ...f, nextDueDate: e.target.value })} /></label><div className="formgrid"><label>Cuenta habitual<select value={f.accountId} onChange={(e) => setF({ ...f, accountId: e.target.value })}><option value="">Elegir al pagar</option>{accounts.map((x) => <option value={x.id} key={x.id}>{x.name}</option>)}</select></label><label>Categoría{f.kind === "expense" ? "*" : ""}<select required={f.kind === "expense"} value={f.categoryId} onChange={(e) => setF({ ...f, categoryId: e.target.value })}><option value="">{f.kind === "expense" ? "Selecciona…" : "Sin categoría"}</option>{cats.map((x) => <option value={x.id} key={x.id}>{x.name}</option>)}</select></label></div>{f.kind === "expense" ? <div className="infoBox"><b>Provisión automática</b><span>Esta obligación aparecerá en el presupuesto del mes de su vencimiento. No tendrás que crear una asignación duplicada.</span></div> : <div className="infoBox"><b>Ingreso previsto automático</b><span>Si la frecuencia es mensual, semanal o anual, cada ocurrencia aparecerá automáticamente en el presupuesto como ingreso esperado del mes.</span></div>}<div className="formActions"><button type="button" onClick={close}>Cancelar</button><button className="primary">{editing ? "Guardar cambios" : "Crear obligación"}</button></div></form></Modal>;
}

function Goals({ data, act, onNew }: { data: AppData; act: ActionFn; onNew: () => void }) {
  const [contribution, setContribution] = useState<string | null>(null), [amount, setAmount] = useState("");
  return <section className="panel"><div className="panelHead"><div><h2>Metas de ahorro</h2><p className="soft">Una reserva reduce el dinero sin comprometer, pero no crea un gasto hasta que exista una transacción.</p></div><button className="primary" onClick={onNew}>＋ Meta</button></div>{data.finance.goals.length ? <div className="goalGrid">{data.finance.goals.map((g) => { const pct = g.targetMinor ? g.reservedMinor / g.targetMinor * 100 : 0, linkedTask = data.tasks.find((t) => t.id === g.linkedTaskId); return <article className="goalCard" key={g.id}><div className="goalTop"><span className={`status ${g.status}`}>{g.status === "funded" ? "Financiada" : "Activa"}</span><small>{g.targetDate ? dateLabel(g.targetDate) : "Sin fecha objetivo"}</small></div><h3>{g.title}</h3>{linkedTask && <p>Vinculada a: {linkedTask.title}</p>}<strong>{money(g.reservedMinor)}<small>de {money(g.targetMinor)}</small></strong><MiniProgress value={pct} tone={pct >= 100 ? "green" : "purple"} /><div className="goalFooter"><span>{Math.round(pct)}% · faltan {money(Math.max(0, g.targetMinor - g.reservedMinor))}</span>{contribution === g.id ? <div className="payInline"><input autoFocus type="number" min="0.01" step="0.01" value={amount} onChange={(e) => setAmount(e.target.value)} /><button className="primary" onClick={async () => { await act("finance.goal.contribute", { goalId: g.id, amountMinor: minor(amount), occurredOn: localToday(), note: "Aporte" }); setContribution(null); setAmount(""); }}>Aportar</button></div> : <button onClick={() => setContribution(g.id)}>Añadir reserva</button>}</div></article>; })}</div> : <Empty>Crea una meta para separar dinero destinado a una compra o proyecto.</Empty>}</section>;
}

function GoalForm({ data, act, close }: { data: AppData; act: ActionFn; close: () => void }) {
  const expenseCategories = data.finance.categories.filter((x) => x.kind === "expense");
  const [f, setF] = useState({ title: "", target: "", targetDate: "", priority: "media", accountId: "", categoryId: "", coveredByBudget: false, linkedTaskId: "", linkedProjectId: "" });
  return <Modal title="Nueva meta de ahorro" onClose={close}><form className="form" onSubmit={async (e) => { e.preventDefault(); await act("finance.goal.create", { ...f, targetMinor: minor(f.target) }); close(); }}><label>Nombre*<input required autoFocus value={f.title} onChange={(e) => setF({ ...f, title: e.target.value })} /></label><div className="formgrid"><label>Objetivo RD$*<input required type="number" min="0.01" step="0.01" value={f.target} onChange={(e) => setF({ ...f, target: e.target.value })} /></label><label>Fecha objetivo<input type="date" value={f.targetDate} onChange={(e) => setF({ ...f, targetDate: e.target.value })} /></label></div><label>Prioridad<select value={f.priority} onChange={(e) => setF({ ...f, priority: e.target.value })}><option value="alta">Alta</option><option value="media">Media</option><option value="baja">Baja</option></select></label><div className="formgrid"><label>Vincular a tarea<select value={f.linkedTaskId} onChange={(e) => setF({ ...f, linkedTaskId: e.target.value })}><option value="">Sin tarea</option>{data.tasks.filter((x) => !x.archived).map((x) => <option value={x.id} key={x.id}>{x.title}</option>)}</select></label><label>Vincular a proyecto<select value={f.linkedProjectId} onChange={(e) => setF({ ...f, linkedProjectId: e.target.value })}><option value="">Sin proyecto</option>{data.projects.map((x) => <option value={x.id} key={x.id}>{x.name}</option>)}</select></label></div><div className="formgrid"><label>Cuenta de referencia<select value={f.accountId} onChange={(e) => setF({ ...f, accountId: e.target.value })}><option value="">Sin cuenta específica</option>{data.finance.accounts.filter((x) => !x.archived).map((x) => <option value={x.id} key={x.id}>{x.name}</option>)}</select></label><label>Categoría presupuestaria<select value={f.categoryId} onChange={(e) => setF({ ...f, categoryId: e.target.value, coveredByBudget: !!e.target.value && f.coveredByBudget })}><option value="">No vincular al presupuesto</option>{expenseCategories.map((x) => <option value={x.id} key={x.id}>{x.name}</option>)}</select></label></div>{f.categoryId && <label className="checkLabel"><input type="checkbox" checked={f.coveredByBudget} onChange={(e) => setF({ ...f, coveredByBudget: e.target.checked })} />Descontar los aportes de la categoría presupuestaria del mes</label>}<div className="infoBox"><b>Sin doble conteo</b><span>La reserva reduce la disponibilidad. Si la vinculas al presupuesto, cada aporte también consumirá esa categoría y el total comprometido se mantendrá correcto.</span></div><div className="formActions"><button type="button" onClick={close}>Cancelar</button><button className="primary">Crear meta</button></div></form></Modal>;
}

function Reports({ data, exportCsv }: { data: AppData; exportCsv: () => void }) {
  const f = data.finance, confirmed = f.transactions.filter((x) => x.status === "confirmed" && x.occurredOn <= localToday()), byCat = f.categories.filter((c) => c.kind === "expense").map((c) => ({ ...c, total: confirmed.reduce((sum, transaction) => sum + (transaction.type === "expense" && transaction.categoryId === c.id ? transaction.amountMinor : 0) + (transaction.feeMinor > 0 && (transaction.feeCategoryId || (transaction.type === "transfer" ? transaction.categoryId : null)) === c.id ? transaction.feeMinor : 0), 0) })).filter((x) => x.total > 0).sort((a, b) => b.total - a.total), max = Math.max(...byCat.map((x) => x.total), 1);
  const taskCosts = data.tasks.map((t) => ({ task: t, spent: f.taskSpend[t.id] || 0 })).filter((x) => x.spent).sort((a, b) => b.spent - a.spent);
  return <><div className="twocol"><section className="panel"><div className="panelHead"><h2>Gastos por categoría</h2><button onClick={exportCsv}>Descargar CSV</button></div>{byCat.length ? byCat.map((x) => <div className="reportBar" key={x.id}><span>{x.name}<b>{money(x.total)}</b></span><div><i style={{ width: `${x.total / max * 100}%`, background: x.color }} /></div></div>) : <Empty>No hay gastos confirmados.</Empty>}</section><section className="panel"><h2>Flujo proyectado</h2><p className="soft">Los ingresos futuros no se consideran disponibles hoy; sólo aparecen en esta proyección.</p>{f.cashflow.length ? <div className="projectionChart"><svg viewBox="0 0 500 160" role="img" aria-label="Proyección de saldo"><polyline fill="none" stroke="#2463eb" strokeWidth="5" strokeLinecap="round" strokeLinejoin="round" points={f.cashflow.map((x, i) => `${20 + i * (460 / Math.max(1, f.cashflow.length - 1))},${140 - ((x.balanceMinor - Math.min(...f.cashflow.map((z) => z.balanceMinor))) / Math.max(1, Math.max(...f.cashflow.map((z) => z.balanceMinor)) - Math.min(...f.cashflow.map((z) => z.balanceMinor)))) * 110}`).join(" ")} /></svg>{f.cashflow.map((x) => <div className="cashPoint" key={x.date}><span>{dateLabel(x.date)}</span><b className={x.changeMinor < 0 ? "negative" : "positive"}>{x.changeMinor > 0 ? "+" : ""}{money(x.changeMinor)}</b><strong>{money(x.balanceMinor)}</strong></div>)}</div> : <Empty>Sin movimientos futuros u obligaciones pendientes.</Empty>}</section></div><section className="panel"><div className="panelHead"><div><h2>Estimado frente a gasto real por tarea</h2><p className="soft">La comparación convierte el estimado histórico en centavos sólo para visualizar; nunca lo suma nuevamente como gasto.</p></div></div><div className="tableWrap"><table><thead><tr><th>Tarea</th><th>Estimado</th><th>Gasto confirmado</th><th>Diferencia</th></tr></thead><tbody>{taskCosts.map(({ task, spent }) => <tr key={task.id}><td>{task.title}</td><td>{legacyMoney(task.estimate)}</td><td>{money(spent)}</td><td className={task.estimate != null && spent > task.estimate * 100 ? "negative" : ""}>{task.estimate == null ? "Sin estimar" : money(task.estimate * 100 - spent)}</td></tr>)}</tbody></table></div></section></>;
}

export function ActivityModule({ data }: { data: AppData }) {
  const task = (id: string) => data.tasks.find((x) => x.id === id)?.title || "Tarea";
  const activity = [
    ...data.notes.map((x) => ({ id: `note-${x.id}`, at: x.createdAt, title: `Nota en ${task(x.taskId)}`, detail: x.text, kind: "Bitácora" })),
    ...data.finance.audits.map((x) => ({ id: `audit-${x.id}`, at: x.occurredAt, title: `${({ transaction: "Movimiento", account: "Cuenta", obligation: "Obligación", goal: "Meta", event: "Evento", settings: "Configuración" } as Record<string, string>)[x.entityType] || x.entityType} · ${({ created: "creado", updated: "actualizado", voided: "anulado", contribution: "aporte registrado", paid: "pagado", partially_paid: "pago parcial", cancelled: "cancelado", archived: "archivado", set: "configurado" } as Record<string, string>)[x.action] || x.action}`, detail: "Cambio persistido y auditado", kind: "Sistema" })),
  ].sort((a, b) => b.at.localeCompare(a.at));
  return <section className="panel"><div className="panelHead"><div><h2>Bitácora integral</h2><p className="soft">Notas de tareas y cambios críticos de calendario y finanzas, ordenados por fecha.</p></div><span className="soft">{activity.length} registros</span></div>{activity.length ? <div className="activityTimeline">{activity.map((x) => <article key={x.id}><i /><div><span>{x.kind} · {new Date(x.at).toLocaleString("es-DO", { dateStyle: "medium", timeStyle: "short" })}</span><b>{x.title}</b><p>{x.detail}</p></div></article>)}</div> : <Empty>No hay actividad todavía.</Empty>}</section>;
}

export function SettingsModule({ data, act }: { data: AppData; act: ActionFn }) {
  const [buffer, setBuffer] = useState(String(data.finance.settings.safetyBufferMinor / 100));
  const [sameBankRate, setSameBankRate] = useState(String(data.finance.settings.transferSameBankRateBps / 100));
  const [achRate, setAchRate] = useState(String(data.finance.settings.transferAchRateBps / 100));
  const [lbtrSurcharge, setLbtrSurcharge] = useState(String(data.finance.settings.transferLbtrSurchargeMinor / 100));
  const [bankProfiles, setBankProfiles] = useState(Object.entries(data.finance.settings.transferBankFees || {}).map(([name, fee]) => `${name}|${fee.achRateBps / 100}|${fee.lbtrSurchargeMinor / 100}`).join("\n"));
  const fileRef = useRef<HTMLInputElement>(null);
  const rateBps = (value: string) => Math.round((Number(value) || 0) * 100);
  const download = () => { const blob = new Blob([JSON.stringify({ version: 2, exportedAt: new Date().toISOString(), ...data }, null, 2)], { type: "application/json" }); const a = document.createElement("a"); a.href = URL.createObjectURL(blob); a.download = `vida-en-orden-respaldo-${localToday()}.json`; a.click(); URL.revokeObjectURL(a.href); };
  const restore = async (file?: File) => { if (!file) return; const parsed = JSON.parse(await file.text()); if (!window.confirm("Este respaldo reemplazará los datos actuales de tareas, calendario y finanzas. ¿Continuar?")) return; await act("backup.restore", { data: parsed }); if (fileRef.current) fileRef.current.value = ""; };
  return <><div className="twocol"><section className="panel"><h2>Preferencias financieras</h2><p className="soft">El colchón se descuenta del saldo sin comprometer, pero continúa formando parte de tu saldo líquido.</p><form className="form settingsForm" onSubmit={async (e) => { e.preventDefault(); const profiles = Object.fromEntries(bankProfiles.split("\n").map((line) => line.split("|").map((x) => x.trim())).filter((row) => row[0]).map(([name, ach, surcharge]) => [name, { achRateBps: rateBps(ach || "0"), lbtrSurchargeMinor: minor(surcharge || "0") }])); await act("finance.settings.update", { safetyBufferMinor: minor(buffer), timezone: data.finance.settings.timezone, transferSameBankRateBps: rateBps(sameBankRate), transferAchRateBps: rateBps(achRate), transferLbtrSurchargeMinor: minor(lbtrSurcharge), transferBankFees: profiles }); }}><label>Colchón de seguridad RD$<input type="number" min="0" step="0.01" value={buffer} onChange={(e) => setBuffer(e.target.value)} /></label><label>Zona horaria<input value="America/Santo_Domingo" disabled /></label><h3 className="settingsSubhead">Comisiones de transferencias</h3><p className="soft">Mismo banco y ACH se calculan como porcentaje del importe. LBTR aplica el porcentaje ACH más un cargo fijo adicional.</p><div className="formgrid"><label>Mismo banco (%)<input type="number" min="0" step="0.01" value={sameBankRate} onChange={(e) => setSameBankRate(e.target.value)} /></label><label>ACH interbancaria predeterminada (%)<input type="number" min="0" step="0.01" value={achRate} onChange={(e) => setAchRate(e.target.value)} /></label></div><label>Cargo adicional LBTR / inmediata (RD$)<input type="number" min="0" step="0.01" value={lbtrSurcharge} onChange={(e) => setLbtrSurcharge(e.target.value)} /></label><label>Tarifas específicas por banco<p className="soft">Una línea por banco: <code>Banco|ACH %|Cargo LBTR RD$</code></p><textarea rows={4} value={bankProfiles} onChange={(e) => setBankProfiles(e.target.value)} placeholder="Banco Popular|0|100\nBanreservas|0|125" /></label><div className="infoBox"><b>Cómo se calcula</b><span>Si los bancos coinciden, se aplica el porcentaje de mismo banco. Si son distintos, se usa el porcentaje ACH del banco destino o el predeterminado. LBTR suma además su cargo fijo en RD$.</span></div><div className="formActions"><button className="primary">Guardar preferencias</button></div></form></section><section className="panel"><h2>Respaldo y recuperación</h2><p className="soft">El archivo incluye tareas, notas, eventos, proyectos y datos financieros. La restauración valida identificadores y conserva la estructura recursiva.</p><div className="backupActions"><button className="primary" onClick={download}>Descargar respaldo JSON</button><button onClick={() => fileRef.current?.click()}>Restaurar respaldo</button><input ref={fileRef} hidden type="file" accept="application/json,.json" onChange={(e) => restore(e.target.files?.[0]).catch((error) => alert(error instanceof Error ? error.message : "No se pudo restaurar"))} /></div></section></div><section className="panel"><h2>Privacidad y alcance actual</h2><div className="privacyGrid"><div><b>Finanzas y eventos</b><span>Privados para cada cuenta de ChatGPT con acceso al Site.</span></div><div><b>Tareas actuales</b><span>Compartidas con las personas autorizadas en este Site, como en la versión anterior.</span></div><div><b>Próxima fase</b><span>Espacios personales, compartidos y vista general diferenciada. Se incorporará al final, según lo acordado.</span></div></div></section></>;
}
